import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

"use client";

import { cn } from "@/registry/lib/utils";
import { cva, VariantProps } from "class-variance-authority";
import { ComponentProps, forwardRef, ReactNode } from "react";

//  Main Card
const cardMainVariant = cva(
  [
    "w-full max-w-sm overflow-hidden shadow-md transition-all duration-300",
    "bg-white text-black",
  ],
  {
    variants: {
      shadow: {
        sm: "shadow-sm",
        md: "shadow-md",
        lg: "shadow-lg",
        xl: "shadow-xl",
      },
      radius: {
        none: "rounded-none",
        sm: "rounded-sm",
        md: "rounded-md",
        lg: "rounded-lg",
        xl: "rounded-xl",
      },
    },
    defaultVariants: {
      radius: "xl",
      shadow: "md",
    },
  }
);

type CardMainProps = ComponentProps<"div"> &
  VariantProps<typeof cardMainVariant> & { children: ReactNode };

const CardMain = forwardRef<HTMLDivElement, CardMainProps>(
  ({ children, radius, shadow, className, ...props }, ref) => {
    return (
      <div
        className={cn(cardMainVariant({ radius, shadow }), className)}
        ref={ref}
        {...props}
      >
        {children}
      </div>
    );
  }
);

CardMain.displayName="Card.Main"

// Content Area
type CardAreaProps = ComponentProps<"div"> & { children: ReactNode };

const CardArea = forwardRef<HTMLDivElement, CardAreaProps>(
  ({ children, className, ...props }, ref) => (
    <div className={cn(className)} ref={ref} {...props}>
      {children}
    </div>
  )
);

CardArea.displayName="Card.Area"

// Image Section
const cardImageVariant = cva(["w-full h-full object-cover"], {
  variants: {
    radius: {
      none: "rounded-none",
      sm: "rounded-sm",
      md: "rounded-md",
      lg: "rounded-lg",
      xl: "rounded-xl",
    },
    fit: {
      cover: "cover",
      contain: "contain",
      fill: "fill",
      none: "none",
      scale: "scale-down",
    },
  },
  defaultVariants: { radius: "xl", fit: "cover" },
});

type CardImageProps = ComponentProps<"img"> &
  VariantProps<typeof cardImageVariant>;

const CardImage = forwardRef<HTMLImageElement, CardImageProps>(
  ({ radius, fit, className, ...props }, ref) => (
    <img
      ref={ref}
      className={cn(
        cardImageVariant({ radius }),
        fit && `object-${fit}`,
        className
      )}
      {...props}
    />
  )
);

CardImage.displayName="Card.Image"

export const Card = {
  Main: CardMain,
  Area: CardArea,
  Image: CardImage,
};

"use client";

import { ComponentProps, forwardRef, useRef, useState } from "react";
import { cva, VariantProps } from "class-variance-authority";
import { cn } from "@/registry/lib/utils";
const buttonVariants = cva(
  [
    "bg-black text-white border-2 border-transparent rounded-md transition-all duration-300",
  ],
  {
    variants: {
      variant: {
        solid: "focus:border-white bg-black focus:ring-black",
        primary: "focus:border-white bg-blue-500  focus:ring-blue-500",
        success: "focus:border-white  bg-green-500 focus:ring-green-500",
        danger: "focus:border-white  bg-red-500 focus:ring-red-500",
      },
      size: {
        sm: "px-4 py-2 text-sm",
        md: "px-4 py-2 text-base",
        lg: "px-6 py-3 text-lg",
      },
      radius: {
        sm: "rounded-sm",
        md: "rounded-md",
        lg: "rounded-lg",
        xl: "rounded-xl",
        full: "rounded-full",
      },
    },
    defaultVariants: {
      variant: "solid",
      size: "md",
      radius: "md",
    },
  }
);

type ButtonProps = ComponentProps<"button"> &
  VariantProps<typeof buttonVariants>;

export const ButtonRing = forwardRef<HTMLButtonElement, ButtonProps>(
  ({ variant, size, radius, className, ...props }, ref) => {
    const btnRef = useRef<HTMLButtonElement>(null);
    const [activeRing, setActiveRing] = useState(false);

    const handleClick = () => {
      setActiveRing(true);
      btnRef.current?.focus();

      setTimeout(() => {
        setActiveRing(false);
        btnRef.current?.blur();
      }, 5000);
    };

    return (
      <button
        ref={(node) => {
          btnRef.current = node;
          if (typeof ref === "function") ref(node);
          else if (ref) ref.current = node;
        }}
        className={cn(
          buttonVariants({ variant, size, radius, className }),
          activeRing && "ring-2"
        )}
        onClick={(e) => {
          handleClick();
          props.onClick?.(e);
        }}
        {...props}
      >
        {props.children}
      </button>
    );
  }
);

ButtonRing.displayName="ButtonRing"
